def fetch_html(url, headers=None, **_extra):
    import json, os, datetime
    import time, hashlib, re, urllib.parse, urllib.request, urllib.error, socket, ipaddress, html as _html

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0389000" if __import__("os").path.isdir("./environment_mix/0389000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utc_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _utc_day():
        return datetime.datetime.utcnow().date().isoformat()

    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{hashlib.sha256(os.urandom(16)).hexdigest()[:16]}"

    def _normalize_url(u):
        p = urllib.parse.urlsplit(u)
        scheme = (p.scheme or "").lower()
        if scheme not in ("http", "https"):
            return None
        host = (p.hostname or "").strip().lower().rstrip(".")
        if not host:
            return None
        port = p.port
        netloc = host
        if port and not ((scheme == "http" and port == 80) or (scheme == "https" and port == 443)):
            netloc = f"{host}:{port}"
        path = p.path or "/"
        path = urllib.parse.quote(urllib.parse.unquote(path), safe="/%:@")
        query = p.query or ""
        query = urllib.parse.quote_plus(urllib.parse.unquote_plus(query), safe="=&;%:@/?[],-._~")
        frag = ""
        return urllib.parse.urlunsplit((scheme, netloc, path, query, frag))

    _HOP_BY_HOP = {"host", "content-length", "connection", "proxy-connection", "keep-alive", "te", "trailer", "transfer-encoding", "upgrade"}

    def _validate_headers(h):
        if h is None:
            return {}
        if not isinstance(h, dict):
            return None, _err("VALIDATION_ERROR", "headers must be an object")
        out = {}
        total_bytes = 0
        if len(h) > 50:
            return None, _err("VALIDATION_ERROR", "too many headers (max 50)")
        for k, v in h.items():
            if not isinstance(k, str) or not isinstance(v, str):
                return None, _err("VALIDATION_ERROR", "headers keys and values must be strings")
            k_stripped = k.strip()
            if not k_stripped:
                return None, _err("VALIDATION_ERROR", "header name cannot be empty")
            if k_stripped.lower() in _HOP_BY_HOP:
                return None, _err("VALIDATION_ERROR", f"header '{k_stripped}' is not allowed")
            if "\r" in k_stripped or "\n" in k_stripped or "\r" in v or "\n" in v:
                return None, _err("VALIDATION_ERROR", "invalid header value")
            out[k_stripped] = v
            total_bytes += len(k_stripped.encode("utf-8")) + len(v.encode("utf-8")) + 4
            if total_bytes > 8192:
                return None, _err("VALIDATION_ERROR", "headers too large (max 8192 bytes)")
        return out, None

    def _headers_hash(h):
        items = sorted((k.lower(), v) for k, v in (h or {}).items())
        b = json.dumps(items, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _match_host_pattern(host, pattern):
        host = host.lower().rstrip(".")
        pattern = pattern.lower().rstrip(".")
        if pattern.startswith("*."):
            suf = pattern[1:]  # ".example.com"
            return host.endswith(suf) and host != pattern[2:]
        return host == pattern

    def _policy_decision(client_id, host, policies):
        relevant_client = [p for p in policies if p.get("status") == "active" and p.get("api_client_id") == client_id]
        relevant_global = [p for p in policies if p.get("status") == "active" and (p.get("api_client_id") is None)]
        def eval_rules(rules):
            matches = [p for p in rules if _match_host_pattern(host, p.get("host_pattern") or "")]
            if any(p.get("policy") == "deny" for p in matches):
                return "deny"
            if any(p.get("policy") == "allow" for p in matches):
                return "allow"
            return None
        d = eval_rules(relevant_client)
        if d is not None:
            return d
        d = eval_rules(relevant_global)
        if d is not None:
            return d
        return None

    def _is_private_ip(ip_str):
        try:
            ip = ipaddress.ip_address(ip_str)
        except Exception:
            return False
        return (
            ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved or
            ip.is_multicast or ip.is_unspecified
        )

    def _resolve_ips(host, port):
        try:
            infos = socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)
        except socket.gaierror:
            return None, "dns"
        ips = []
        for fam, _, _, _, sockaddr in infos:
            if fam == socket.AF_INET:
                ips.append(sockaddr[0])
            elif fam == socket.AF_INET6:
                ips.append(sockaddr[0])
        return list(dict.fromkeys(ips)), None

    # Minimal request log dynamics (persist per call) stored in fetch_requests as audit trail
    t0 = time.time()
    now = _utc_now()
    tool_name = "fetch_html"

    # Validate url
    if not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "url is required and must be a string")
    if not re.match(r"^https?://", url.strip(), flags=re.I):
        return _err("VALIDATION_ERROR", "url must start with http:// or https://")
    url_in = url.strip()
    url_norm = _normalize_url(url_in)
    if url_norm is None:
        return _err("VALIDATION_ERROR", "url is invalid")

    # Validate headers
    headers_valid, e = _validate_headers(headers)
    if e:
        return e

    # Load datastore
    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    reqs = _load("fetch_requests.json")
    resps = _load("fetch_responses.json")
    policies = _load("host_access_policies.json")

    # Ambient auth: choose an active client with at least one active key if any exist; otherwise allow internal call (null key) only if an active client exists
    active_clients = [c for c in clients if c.get("status") == "active"]
    if not active_clients:
        return _err("UNAUTHORIZED", "no active client available")
    # choose client that can serve: prefer one with active key
    active_key_by_client = {}
    for k in keys:
        if k.get("status") == "active":
            active_key_by_client.setdefault(k.get("api_client_id"), []).append(k)
    client = None
    api_key = None
    for c in active_clients:
        ks = active_key_by_client.get(c.get("id")) or []
        if ks:
            client = c
            api_key = ks[0]
            break
    if client is None:
        client = active_clients[0]
        api_key = None

    client_id = client.get("id")
    api_key_id = api_key.get("id") if api_key else None

    # Quota: reset if quota_day not today
    day = _utc_day()
    if client.get("quota_day") != day:
        client["quota_day"] = day
        client["requests_used_today"] = 0
        client["updated_at"] = now

    # Prepare fetch_requests row (always exactly one per call)
    cache_key = hashlib.sha256(
        (url_norm + "|" + tool_name + "|" + _headers_hash(headers_valid)).encode("utf-8")
    ).hexdigest()

    fetch_request_id = _new_id("fr")
    fr = {
        "id": fetch_request_id,
        "api_client_id": client_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "url": url_in,
        "url_normalized": url_norm,
        "headers": headers_valid if headers is not None else None,
        "status": "queued",
        "attempt": 1,
        "cache_policy": "allow_cache",
        "cache_key": cache_key,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(fr)

    # Helper to fail request with a response
    def _fail(error_type, error_message, upstream_status_code=None, upstream_content_type=None, final_url=None, redirect_count=0, response_headers=None, elapsed_ms=None, parse_error=None):
        nonlocal fr, reqs, resps
        # transition queued -> running -> failed is legal; but we can go queued->running->failed for audit
        fr["status"] = "running"
        fr["started_at"] = now
        fr["updated_at"] = _utc_now()
        finished = _utc_now()
        fr["status"] = "failed"
        fr["finished_at"] = finished
        fr["updated_at"] = finished
        resp = {
            "id": _new_id("fresp"),
            "fetch_request_id": fetch_request_id,
            "upstream_status_code": upstream_status_code,
            "upstream_content_type": upstream_content_type,
            "final_url": final_url,
            "redirect_count": int(redirect_count or 0),
            "response_headers": response_headers,
            "elapsed_ms": elapsed_ms,
            "body_bytes": None,
            "body_truncated": False,
            "content_format": "html",
            "content_text": None,
            "content_json": None,
            "parse_error": parse_error,
            "error_type": error_type,
            "error_message": error_message,
            "created_at": _utc_now(),
            "updated_at": _utc_now(),
        }
        resps.append(resp)
        # persist
        _save("fetch_requests.json", reqs)
        _save("fetch_responses.json", resps)
        _save("api_clients.json", clients)
        if api_key:
            api_key["last_used_at"] = _utc_now()
            api_key["updated_at"] = _utc_now()
            _save("api_keys.json", keys)
        latency = int((time.time() - t0) * 1000)
        return {
            "fetch_request": fr,
            "response": {
                "final_url": final_url,
                "status_code": upstream_status_code,
                "content_type": upstream_content_type,
                "elapsed_ms": elapsed_ms if elapsed_ms is not None else latency,
                "body_truncated": False,
            },
            "html": None,
            "error": {"type": error_type, "message": error_message},
        }

    # Enforce client active
    if client.get("status") != "active":
        fr["updated_at"] = _utc_now()
        _save("fetch_requests.json", reqs)
        return _err("UNAUTHORIZED", "client is not active")

    # Enforce quota before any upstream work
    quota = int(client.get("daily_request_quota") or 0)
    used = int(client.get("requests_used_today") or 0)
    if quota >= 0 and used + 1 > quota:
        # record as failed blocked(quota) without upstream
        out = _fail("blocked", "quota exceeded", upstream_status_code=None, upstream_content_type=None, final_url=None, redirect_count=0, response_headers=None, elapsed_ms=0)
        out["error"]["code"] = "QUOTA_EXCEEDED"
        return out

    # Host policy (allowlist-only assumed)
    parsed = urllib.parse.urlsplit(url_norm)
    host = parsed.hostname
    pol = _policy_decision(client_id, host, policies)
    allowlist_only = True
    if pol == "deny" or (allowlist_only and pol != "allow"):
        return _fail("blocked", "host blocked by policy", final_url=None, elapsed_ms=0)

    # DNS resolve + private network block
    port = parsed.port or (443 if parsed.scheme == "https" else 80)
    ips, dns_err = _resolve_ips(host, port)
    if dns_err == "dns":
        return _fail("dns", "DNS resolution failed", final_url=None, elapsed_ms=0)
    if any(_is_private_ip(ip) for ip in (ips or [])):
        return _fail("blocked", "destination resolves to private/internal network address", final_url=None, elapsed_ms=0)

    # Proceed to running
    fr["status"] = "running"
    fr["started_at"] = _utc_now()
    fr["updated_at"] = fr["started_at"]

    # Upstream fetch
    timeout_ms = int(client.get("default_timeout_ms") or 10000)
    timeout_s = max(1.0, timeout_ms / 1000.0)
    max_bytes = int(client.get("max_response_bytes") or 1048576)
    t_up0 = time.time()
    upstream_status = None
    upstream_ct = None
    final_url = None
    resp_headers_saved = None
    redirect_count = 0
    body = b""
    truncated = False
    try:
        req = urllib.request.Request(url_norm, headers=headers_valid, method="GET")
        opener = urllib.request.build_opener(urllib.request.HTTPRedirectHandler())
        with opener.open(req, timeout=timeout_s) as r:
            final_url = r.geturl()
            upstream_status = getattr(r, "status", None)
            upstream_ct = r.headers.get("Content-Type")
            # save some headers
            resp_headers_saved = {}
            for hk in ("Content-Type", "Content-Length", "Last-Modified", "ETag", "Cache-Control"):
                hv = r.headers.get(hk)
                if hv is not None:
                    resp_headers_saved[hk] = hv
            # read with cap
            while True:
                chunk = r.read(64 * 1024)
                if not chunk:
                    break
                if len(body) + len(chunk) > max_bytes:
                    remain = max_bytes - len(body)
                    if remain > 0:
                        body += chunk[:remain]
                    truncated = True
                    break
                body += chunk
        # best-effort redirect count (urllib doesn't expose; infer via history not available)
        redirect_count = 0
    except urllib.error.HTTPError as he:
        upstream_status = he.code
        upstream_ct = he.headers.get("Content-Type") if he.headers else None
        final_url = he.geturl()
        elapsed_ms = int((time.time() - t_up0) * 1000)
        return _fail("http_error", f"upstream HTTP error {he.code}", upstream_status_code=upstream_status, upstream_content_type=upstream_ct, final_url=final_url, redirect_count=0, response_headers=None, elapsed_ms=elapsed_ms)
    except urllib.error.URLError as ue:
        reason = getattr(ue, "reason", None)
        elapsed_ms = int((time.time() - t_up0) * 1000)
        if isinstance(reason, socket.timeout):
            return _fail("timeout", "upstream request timed out", final_url=final_url, elapsed_ms=elapsed_ms)
        if isinstance(reason, ssl.SSLError) if "ssl" in globals() else False:
            return _fail("tls", "TLS error", final_url=final_url, elapsed_ms=elapsed_ms)
        return _fail("connect", f"connection error: {reason}", final_url=final_url, elapsed_ms=elapsed_ms)
    except socket.timeout:
        elapsed_ms = int((time.time() - t_up0) * 1000)
        return _fail("timeout", "upstream request timed out", final_url=final_url, elapsed_ms=elapsed_ms)
    except Exception as ex:
        # Unexpected runtime: return error object (do not mask programming errors normally, but contract says must not raise)
        return _err("UNKNOWN", "unexpected error", detail=str(ex))

    elapsed_ms = int((time.time() - t_up0) * 1000)

    # Success: increment quota counter (only for successful authenticated tool call; we treat ambient auth as authenticated)
    client["requests_used_today"] = used + 1
    client["updated_at"] = _utc_now()
    if api_key:
        api_key["last_used_at"] = _utc_now()
        api_key["updated_at"] = api_key["last_used_at"]

    # Decode as html text (best-effort)
    charset = "utf-8"
    if upstream_ct:
        m = re.search(r"charset=([^\s;]+)", upstream_ct, re.I)
        if m:
            charset = m.group(1).strip("\"'")[:40]
    try:
        text = body.decode(charset, errors="replace")
    except Exception:
        text = body.decode("utf-8", errors="replace")

    stored_bytes = len(text.encode("utf-8"))
    body_truncated = truncated or (stored_bytes > max_bytes)
    if stored_bytes > max_bytes:
        # hard truncate by bytes
        b2 = text.encode("utf-8")[:max_bytes]
        text = b2.decode("utf-8", errors="ignore")
        stored_bytes = len(text.encode("utf-8"))
        body_truncated = True

    # Write response row
    fr["status"] = "succeeded"
    fr["finished_at"] = _utc_now()
    fr["updated_at"] = fr["finished_at"]
    resp_row = {
        "id": _new_id("fresp"),
        "fetch_request_id": fetch_request_id,
        "upstream_status_code": upstream_status,
        "upstream_content_type": upstream_ct,
        "final_url": final_url,
        "redirect_count": int(redirect_count),
        "response_headers": resp_headers_saved,
        "elapsed_ms": elapsed_ms,
        "body_bytes": stored_bytes,
        "body_truncated": bool(body_truncated),
        "content_format": "html",
        "content_text": text,
        "content_json": None,
        "parse_error": None,
        "error_type": None,
        "error_message": None,
        "created_at": _utc_now(),
        "updated_at": _utc_now(),
    }
    # Ensure at most one response per request
    if any(r.get("fetch_request_id") == fetch_request_id for r in resps):
        return _err("CONFLICT", "response already exists for fetch_request_id")
    resps.append(resp_row)

    _save("fetch_requests.json", reqs)
    _save("fetch_responses.json", resps)
    _save("api_clients.json", clients)
    if api_key:
        _save("api_keys.json", keys)

    return {
        "fetch_request": fr,
        "response": {
            "final_url": final_url,
            "status_code": upstream_status,
            "content_type": upstream_ct,
            "elapsed_ms": elapsed_ms,
            "body_bytes": stored_bytes,
            "body_truncated": bool(body_truncated),
        },
        "html": text,
    }

def fetch_markdown(url, headers=None, **_extra):
    import json, os, datetime
    import time, hashlib, re, urllib.parse, urllib.request, urllib.error, socket, ipaddress
    from html.parser import HTMLParser

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0389000" if __import__("os").path.isdir("./environment_mix/0389000") else "/app/database")

