    def _validate_headers(h):
        if h is None:
            return {}
        if not isinstance(h, dict):
            return None, _err("VALIDATION_ERROR", "headers must be an object")
        out = {}
        total_bytes = 0
        if len(h) > 50:
            return None, _err("VALIDATION_ERROR", "too many headers (max 50)")
        for k, v in h.items():
            if not isinstance(k, str) or not isinstance(v, str):
                return None, _err("VALIDATION_ERROR", "headers keys and values must be strings")
            k_stripped = k.strip()
            if not k_stripped:
                return None, _err("VALIDATION_ERROR", "header name cannot be empty")
            if k_stripped.lower() in _HOP_BY_HOP:
                return None, _err("VALIDATION_ERROR", f"header '{k_stripped}' is not allowed")
            if "\r" in k_stripped or "\n" in k_stripped or "\r" in v or "\n" in v:
                return None, _err("VALIDATION_ERROR", "invalid header value")
            out[k_stripped] = v
            total_bytes += len(k_stripped.encode("utf-8")) + len(v.encode("utf-8")) + 4
