        reason = getattr(ue, "reason", None)
        if isinstance(reason, socket.timeout):
            return _fail("timeout", "upstream request timed out", final_url=final_url, elapsed_ms=elapsed_ms)
        return _fail("connect", f"connection error: {reason}", final_url=final_url, elapsed_ms=elapsed_ms)
    except socket.timeout:
        elapsed_ms = int((time.time() - t_up0) * 1000)
        return _fail("timeout", "upstream request timed out", final_url=final_url, elapsed_ms=elapsed_ms)
    except Exception as ex:
        return _err("UNKNOWN", "unexpected error", detail=str(ex))

    elapsed_ms = int((time.time() - t_up0) * 1000)

    client["requests_used_today"] = used + 1
    client["updated_at"] = _utc_now()
    if api_key:
        api_key["last_used_at"] = _utc_now()
        api_key["updated_at"] = api_key["last_used_at"]

    charset = "utf-8"
    if upstream_ct:
        m = re.search(r"charset=([^\s;]+)", upstream_ct, re.I)
        if m:
            charset = m.group(1).strip("\"'")[:40]
    try:
        html_text = body.decode(charset, errors="replace")
    except Exception:
        html_text = body.decode("utf-8", errors="replace")

    stripper = _StripHTML()
    try:
        stripper.feed(html_text)
        text = stripper.get_text()
    except Exception:
        text = re.sub(r"\s+", " ", html_text).strip()

    stored_bytes = len(text.encode("utf-8"))
    body_truncated = truncated or (stored_bytes > max_bytes)
    if stored_bytes > max_bytes:
        b2 = text.encode("utf-8")[:max_bytes]
        text = b2.decode("utf-8", errors="ignore")
        stored_bytes = len(text.encode("utf-8"))
        body_truncated = True

    fr["status"] = "succeeded"
    fr["finished_at"] = _utc_now()
    fr["updated_at"] = fr["finished_at"]

    resp_row = {
        "id": _new_id("fresp"),
        "fetch_request_id": fetch_request_id,
        "upstream_status_code": upstream_status,
        "upstream_content_type": upstream_ct,
        "final_url": final_url,
        "redirect_count": 0,
        "response_headers": None,
        "elapsed_ms": elapsed_ms,
        "body_bytes": stored_bytes,
        "body_truncated": bool(body_truncated),
        "content_format": "text",
        "content_text": text,
        "content_json": None,
        "parse_error": None,
        "error_type": None,
        "error_message": None,
        "created_at": _utc_now(),
        "updated_at": _utc_now(),
    }
    if any(r.get("fetch_request_id") == fetch_request_id for r in resps):
        return _err("CONFLICT", "response already exists for fetch_request_id")
    resps.append(resp_row)

    _save("fetch_requests.json", reqs)
    _save("fetch_responses.json", resps)
    _save("api_clients.json", clients)
    if api_key:
        _save("api_keys.json", keys)

    return {
        "fetch_request": fr,
        "response": {
            "final_url": final_url,
            "status_code": upstream_status,
            "content_type": upstream_ct,
            "elapsed_ms": elapsed_ms,
            "body_bytes": stored_bytes,
            "body_truncated": bool(body_truncated),
        },
        "text": text,
    }

def fetch_json(url, headers=None, **_extra):
    import json, os, datetime
    import time, hashlib, re, urllib.parse, urllib.request, urllib.error, socket, ipaddress

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0389000" if __import__("os").path.isdir("./environment_mix/0389000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utc_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _utc_day():
        return datetime.datetime.utcnow().date().isoformat()

    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{hashlib.sha256(os.urandom(16)).hexdigest()[:16]}"

    def _normalize_url(u):
        p = urllib.parse.urlsplit(u)
        scheme = (p.scheme or "").lower()
        if scheme not in ("http", "https"):
            return None
        host = (p.hostname or "").strip().lower().rstrip(".")
        if not host:
            return None
        port = p.port
        netloc = host
        if port and not ((scheme == "http" and port == 80) or (scheme == "https" and port == 443)):
            netloc = f"{host}:{port}"
        path = p.path or "/"
        path = urllib.parse.quote(urllib.parse.unquote(path), safe="/%:@")
        query = p.query or ""
        query = urllib.parse.quote_plus(urllib.parse.unquote_plus(query), safe="=&;%:@/?[],-._~")
        return urllib.parse.urlunsplit((scheme, netloc, path, query, ""))

    _HOP_BY_HOP = {"host", "content-length", "connection", "proxy-connection", "keep-alive", "te", "trailer", "transfer-encoding", "upgrade"}

    def _validate_headers(h):
        if h is None:
            return {}
        if not isinstance(h, dict):
            return None, _err("VALIDATION_ERROR", "headers must be an object")
        out = {}
        total_bytes = 0
        if len(h) > 50:
            return None, _err("VALIDATION_ERROR", "too many headers (max 50)")
        for k, v in h.items():
            if not isinstance(k, str) or not isinstance(v, str):
                return None, _err("VALIDATION_ERROR", "headers keys and values must be strings")
            k_stripped = k.strip()
            if not k_stripped:
                return None, _err("VALIDATION_ERROR", "header name cannot be empty")
            if k_stripped.lower() in _HOP_BY_HOP:
                return None, _err("VALIDATION_ERROR", f"header '{k_stripped}' is not allowed")
            if "\r" in k_stripped or "\n" in k_stripped or "\r" in v or "\n" in v:
                return None, _err("VALIDATION_ERROR", "invalid header value")
            out[k_stripped] = v
            total_bytes += len(k_stripped.encode("utf-8")) + len(v.encode("utf-8")) + 4
            if total_bytes > 8192:
                return None, _err("VALIDATION_ERROR", "headers too large (max 8192 bytes)")
        return out, None

    def _headers_hash(h):
        items = sorted((k.lower(), v) for k, v in (h or {}).items())
        b = json.dumps(items, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _match_host_pattern(host, pattern):
        host = host.lower().rstrip(".")
        pattern = pattern.lower().rstrip(".")
        if pattern.startswith("*."):
            suf = pattern[1:]
            return host.endswith(suf) and host != pattern[2:]
        return host == pattern

    def _policy_decision(client_id, host, policies):
        relevant_client = [p for p in policies if p.get("status") == "active" and p.get("api_client_id") == client_id]
        relevant_global = [p for p in policies if p.get("status") == "active" and (p.get("api_client_id") is None)]
        def eval_rules(rules):
            matches = [p for p in rules if _match_host_pattern(host, p.get("host_pattern") or "")]
            if any(p.get("policy") == "deny" for p in matches):
                return "deny"
            if any(p.get("policy") == "allow" for p in matches):
                return "allow"
            return None
        d = eval_rules(relevant_client)
        if d is not None:
            return d
        d = eval_rules(relevant_global)
        if d is not None:
            return d
        return None

    def _is_private_ip(ip_str):
        try:
            ip = ipaddress.ip_address(ip_str)
        except Exception:
            return False
        return (
            ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved or
            ip.is_multicast or ip.is_unspecified
        )

    def _resolve_ips(host, port):
        try:
            infos = socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)
        except socket.gaierror:
            return None, "dns"
        ips = []
        for fam, _, _, _, sockaddr in infos:
            if fam == socket.AF_INET:
                ips.append(sockaddr[0])
            elif fam == socket.AF_INET6:
                ips.append(sockaddr[0])
        return list(dict.fromkeys(ips)), None

    t0 = time.time()
    now = _utc_now()
    tool_name = "fetch_json"

    if not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "url is required and must be a string")
    if not re.match(r"^https?://", url.strip(), flags=re.I):
        return _err("VALIDATION_ERROR", "url must start with http:// or https://")
    url_in = url.strip()
    url_norm = _normalize_url(url_in)
    if url_norm is None:
        return _err("VALIDATION_ERROR", "url is invalid")

    headers_valid, e = _validate_headers(headers)
    if e:
        return e

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    reqs = _load("fetch_requests.json")
    resps = _load("fetch_responses.json")
    policies = _load("host_access_policies.json")

    active_clients = [c for c in clients if c.get("status") == "active"]
    if not active_clients:
        return _err("UNAUTHORIZED", "no active client available")
    active_key_by_client = {}
    for k in keys:
        if k.get("status") == "active":
            active_key_by_client.setdefault(k.get("api_client_id"), []).append(k)
    client = None
    api_key = None
    for c in active_clients:
        ks = active_key_by_client.get(c.get("id")) or []
        if ks:
            client = c
            api_key = ks[0]
            break
    if client is None:
        client = active_clients[0]
        api_key = None

    client_id = client.get("id")
    api_key_id = api_key.get("id") if api_key else None

    day = _utc_day()
    if client.get("quota_day") != day:
        client["quota_day"] = day
        client["requests_used_today"] = 0
        client["updated_at"] = now

    cache_key = hashlib.sha256((url_norm + "|" + tool_name + "|" + _headers_hash(headers_valid)).encode("utf-8")).hexdigest()

    fetch_request_id = _new_id("fr")
    fr = {
        "id": fetch_request_id,
        "api_client_id": client_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "url": url_in,
        "url_normalized": url_norm,
        "headers": headers_valid if headers is not None else None,
        "status": "queued",
        "attempt": 1,
        "cache_policy": "allow_cache",
        "cache_key": cache_key,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(fr)

    def _persist_all():
        _save("fetch_requests.json", reqs)
        _save("fetch_responses.json", resps)
        _save("api_clients.json", clients)
        if api_key:
            _save("api_keys.json", keys)

    def _fail(error_type, error_message, upstream_status_code=None, upstream_content_type=None, final_url=None, elapsed_ms=None, parse_error=None):
        fr["status"] = "running"
        fr["started_at"] = now
        fr["updated_at"] = _utc_now()
        finished = _utc_now()
        fr["status"] = "failed"
        fr["finished_at"] = finished
        fr["updated_at"] = finished
        resp = {
            "id": _new_id("fresp"),
            "fetch_request_id": fetch_request_id,
            "upstream_status_code": upstream_status_code,
            "upstream_content_type": upstream_content_type,
            "final_url": final_url,
            "redirect_count": 0,
            "response_headers": None,
            "elapsed_ms": elapsed_ms,
            "body_bytes": None,
            "body_truncated": False,
            "content_format": "json",
            "content_text": None,
            "content_json": {} if error_type != "parse_error" else None,
            "parse_error": parse_error,
            "error_type": error_type,
            "error_message": error_message,
            "created_at": _utc_now(),
            "updated_at": _utc_now(),
        }
        # content_json must be not null when content_format=json per schema; but parse_error wants parse_error populated and error_type parse_error.
        if error_type == "parse_error":
            resp["content_json"] = None
        else:
            resp["content_json"] = {}
        resps.append(resp)
        _persist_all()
        if api_key:
            api_key["last_used_at"] = _utc_now()
            api_key["updated_at"] = _utc_now()
            _save("api_keys.json", keys)
        return {
            "fetch_request": fr,
            "response": {"final_url": final_url, "status_code": upstream_status_code, "content_type": upstream_content_type, "elapsed_ms": elapsed_ms},
            "json": None,
            "error": {"type": error_type, "message": error_message},
        }

    if client.get("status") != "active":
        fr["updated_at"] = _utc_now()
        _save("fetch_requests.json", reqs)
        return _err("UNAUTHORIZED", "client is not active")

    quota = int(client.get("daily_request_quota") or 0)
    used = int(client.get("requests_used_today") or 0)
    if quota >= 0 and used + 1 > quota:
        out = _fail("blocked", "quota exceeded", elapsed_ms=0)
        out["error"]["code"] = "QUOTA_EXCEEDED"
        return out

    parsed = urllib.parse.urlsplit(url_norm)
    host = parsed.hostname
    allowlist_only = True
    pol = _policy_decision(client_id, host, policies)
    if pol == "deny" or (allowlist_only and pol != "allow"):
        return _fail("blocked", "host blocked by policy", elapsed_ms=0)

    port = parsed.port or (443 if parsed.scheme == "https" else 80)
    ips, dns_err = _resolve_ips(host, port)
    if dns_err == "dns":
        return _fail("dns", "DNS resolution failed", elapsed_ms=0)
    if any(_is_private_ip(ip) for ip in (ips or [])):
        return _fail("blocked", "destination resolves to private/internal network address", elapsed_ms=0)

    fr["status"] = "running"
    fr["started_at"] = _utc_now()
    fr["updated_at"] = fr["started_at"]

    timeout_ms = int(client.get("default_timeout_ms") or 10000)
    timeout_s = max(1.0, timeout_ms / 1000.0)
    max_bytes = int(client.get("max_response_bytes") or 1048576)
    t_up0 = time.time()
    upstream_status = None
    upstream_ct = None
    final_url = None
    body = b""
    truncated = False
    try:
        req = urllib.request.Request(url_norm, headers=headers_valid, method="GET")
        opener = urllib.request.build_opener(urllib.request.HTTPRedirectHandler())
        with opener.open(req, timeout=timeout_s) as r:
            final_url = r.geturl()
            upstream_status = getattr(r, "status", None)
            upstream_ct = r.headers.get("Content-Type")
            while True:
                chunk = r.read(64 * 1024)
                if not chunk:
                    break
                if len(body) + len(chunk) > max_bytes:
                    remain = max_bytes - len(body)
                    if remain > 0:
                        body += chunk[:remain]
                    truncated = True
                    break
                body += chunk
    except urllib.error.HTTPError as he:
        elapsed_ms = int((time.time() - t_up0) * 1000)
        return _fail("http_error", f"upstream HTTP error {he.code}", upstream_status_code=he.code, upstream_content_type=he.headers.get("Content-Type") if he.headers else None, final_url=he.geturl(), elapsed_ms=elapsed_ms)
    except urllib.error.URLError as ue:
        elapsed_ms = int((time.time() - t_up0) * 1000)
        reason = getattr(ue, "reason", None)
        if isinstance(reason, socket.timeout):
            return _fail("timeout", "upstream request timed out", final_url=final_url, elapsed_ms=elapsed_ms)
        return _fail("connect", f"connection error: {reason}", final_url=final_url, elapsed_ms=elapsed_ms)
    except socket.timeout:
        elapsed_ms = int((time.time() - t_up0) * 1000)
        return _fail("timeout", "upstream request timed out", final_url=final_url, elapsed_ms=elapsed_ms)
    except Exception as ex:
        return _err("UNKNOWN", "unexpected error", detail=str(ex))

    elapsed_ms = int((time.time() - t_up0) * 1000)

    # parse JSON
    text = None
    try:
        text = body.decode("utf-8", errors="replace")
        parsed_json = json.loads(text)
    except Exception as jex:
        # parse failure => request failed with parse_error
        out = _fail("parse_error", "failed to parse JSON", upstream_status_code=upstream_status, upstream_content_type=upstream_ct, final_url=final_url, elapsed_ms=elapsed_ms, parse_error=str(jex))
        return out

    # success => increment quota
    client["requests_used_today"] = used + 1
    client["updated_at"] = _utc_now()
    if api_key:
        api_key["last_used_at"] = _utc_now()
        api_key["updated_at"] = api_key["last_used_at"]

    # store JSON; body_bytes reflects stored payload size (serialized)
    stored_bytes = len(json.dumps(parsed_json, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
    body_truncated = bool(truncated or (stored_bytes > max_bytes))
    if stored_bytes > max_bytes:
        # cannot safely truncate JSON while keeping valid; mark too_large failure instead
        return _fail("too_large", "JSON response too large to store", upstream_status_code=upstream_status, upstream_content_type=upstream_ct, final_url=final_url, elapsed_ms=elapsed_ms)

    fr["status"] = "succeeded"
    fr["finished_at"] = _utc_now()
    fr["updated_at"] = fr["finished_at"]

    resp_row = {
        "id": _new_id("fresp"),
        "fetch_request_id": fetch_request_id,
        "upstream_status_code": upstream_status,
        "upstream_content_type": upstream_ct,
        "final_url": final_url,
        "redirect_count": 0,
        "response_headers": None,
        "elapsed_ms": elapsed_ms,
        "body_bytes": stored_bytes,
        "body_truncated": bool(body_truncated),
        "content_format": "json",
        "content_text": None,
        "content_json": parsed_json,
        "parse_error": None,
        "error_type": None,
        "error_message": None,
        "created_at": _utc_now(),
        "updated_at": _utc_now(),
    }
    if any(r.get("fetch_request_id") == fetch_request_id for r in resps):
        return _err("CONFLICT", "response already exists for fetch_request_id")
    resps.append(resp_row)

    _persist_all()

    return {
        "fetch_request": fr,
        "response": {
            "final_url": final_url,
            "status_code": upstream_status,
            "content_type": upstream_ct,
            "elapsed_ms": elapsed_ms,
            "body_bytes": stored_bytes,
            "body_truncated": bool(body_truncated),
        },
        "json": parsed_json,
    }

def get_me(api_key, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0389000" if __import__("os").path.isdir("./environment_mix/0389000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow()
    now_iso = now.replace(microsecond=0).isoformat() + "Z"
    today = now.date().isoformat()

    def _log(api_client_id, api_key_id, tool_name, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rl_" + hashlib.sha256((now_iso + "|" + tool_name + "|" + str(api_client_id) + "|" + str(api_key_id) + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:24],
            "tool_name": tool_name,
            "api_client_id": api_client_id,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    # Validate input
    if not isinstance(api_key, str) or not api_key.strip():
        # Cannot authenticate => still log anonymous attempt
        _log(None, None, "get_me", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    api_keys = _load("api_keys.json")
    api_clients = _load("api_clients.json")

    # Authenticate: match by id OR key_prefix (client-visible) (never by key_hash)
    key_row = None
    for k in api_keys if isinstance(api_keys, list) else []:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            key_row = k
            break

    if not key_row or key_row.get("status") != "active":
        _log(None, key_row.get("id") if key_row else None, "get_me", "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid or revoked API key")

    client_id = key_row.get("api_client_id")
    client_row = None
    for c in api_clients if isinstance(api_clients, list) else []:
        if c.get("id") == client_id:
            client_row = c
            break

    if not client_row:
        _log(None, key_row.get("id"), "get_me", "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API client not found for provided key")

    # Enforce client permitted to use service: active only
    if client_row.get("status") != "active":
        _log(client_row.get("id"), key_row.get("id"), "get_me", "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Client is not permitted to use the service", client_status=client_row.get("status"))

    # Reset quota day if needed (pragmatic; scheduled job may not exist)
    changed = False
    if client_row.get("quota_day") != today:
        client_row["quota_day"] = today
        client_row["requests_used_today"] = 0
        client_row["updated_at"] = now_iso
        changed = True

    # Update last_used_at
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    changed = True

    if changed:
        # persist modifications back to arrays
        for i, k in enumerate(api_keys):
            if k.get("id") == key_row.get("id"):
                api_keys[i] = key_row
                break
        for i, c in enumerate(api_clients):
            if c.get("id") == client_row.get("id"):
                api_clients[i] = client_row
                break
        _save("api_keys.json", api_keys)
        _save("api_clients.json", api_clients)

    body = {
        "api_client": {
            "id": client_row.get("id"),
            "name": client_row.get("name"),
            "status": client_row.get("status"),
            "default_timeout_ms": client_row.get("default_timeout_ms"),
            "max_response_bytes": client_row.get("max_response_bytes"),
            "daily_request_quota": client_row.get("daily_request_quota"),
            "requests_used_today": client_row.get("requests_used_today"),
            "quota_day": client_row.get("quota_day"),
            "created_at": client_row.get("created_at"),
            "updated_at": client_row.get("updated_at"),
        },
        "api_key": {
            "id": key_row.get("id"),
            "key_prefix": key_row.get("key_prefix"),
            "status": key_row.get("status"),
            "last_used_at": key_row.get("last_used_at"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
        },
        "effective_scopes": ["fetch:read", "fetch:cancel"],
        "quota": {
            "day": client_row.get("quota_day"),
            "daily_request_quota": client_row.get("daily_request_quota"),
            "requests_used_today": client_row.get("requests_used_today"),
            "requests_remaining_today": max(0, int(client_row.get("daily_request_quota") or 0) - int(client_row.get("requests_used_today") or 0))
        }
    }

    _log(client_row.get("id"), key_row.get("id"), "get_me", "ok", (time.time() - t0) * 1000)
    return body

def list_fetch_requests(api_key, limit=None, cursor=None, status=None, url_contains=None, url_normalized=None, created_after=None, created_before=None, tool_name=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0389000" if __import__("os").path.isdir("./environment_mix/0389000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow()
    now_iso = now.replace(microsecond=0).isoformat() + "Z"
    today = now.date().isoformat()

    def _log(api_client_id, api_key_id, tool, st, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rl_" + hashlib.sha256((now_iso + "|" + tool + "|" + str(api_client_id) + "|" + str(api_key_id) + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:24],
            "tool_name": tool,
            "api_client_id": api_client_id,
            "api_key_id": api_key_id,
            "status": st,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    # Validate input
    if not isinstance(api_key, str) or not api_key.strip():
        _log(None, None, "list_fetch_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log(None, None, "list_fetch_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _log(None, None, "list_fetch_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(None, None, "list_fetch_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status filter")

    allowed_tools = {"fetch_html", "fetch_markdown", "fetch_txt", "fetch_json"}
    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in allowed_tools:
            _log(None, None, "list_fetch_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid tool_name filter")

    if url_contains is not None and (not isinstance(url_contains, str)):
        _log(None, None, "list_fetch_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "url_contains must be a string")
    if url_normalized is not None and (not isinstance(url_normalized, str) or not url_normalized.strip()):
        _log(None, None, "list_fetch_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "url_normalized must be a non-empty string")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError(field)
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(ss)

    try:
        dt_after = _parse_dt(created_after, "created_after")
        dt_before = _parse_dt(created_before, "created_before")
    except ValueError as e:
        _log(None, None, "list_fetch_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"Invalid date-time for {str(e)}")

    # Authenticate
    api_keys = _load("api_keys.json")
    api_clients = _load("api_clients.json")

    key_row = None
    for k in api_keys if isinstance(api_keys, list) else []:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            key_row = k
            break
    if not key_row or key_row.get("status") != "active":
        _log(None, key_row.get("id") if key_row else None, "list_fetch_requests", "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid or revoked API key")

    client_row = None
    for c in api_clients if isinstance(api_clients, list) else []:
        if c.get("id") == key_row.get("api_client_id"):
            client_row = c
            break
    if not client_row:
        _log(None, key_row.get("id"), "list_fetch_requests", "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API client not found for provided key")

    # "FORBIDDEN if suspended/deleted" but allowed codes list doesn't include FORBIDDEN; use UNAUTHORIZED.
    if client_row.get("status") != "active":
        _log(client_row.get("id"), key_row.get("id"), "list_fetch_requests", "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Client is not permitted to use the service", client_status=client_row.get("status"))

    # Reset quota day if needed (non-consuming endpoint)
    if client_row.get("quota_day") != today:
        client_row["quota_day"] = today
        client_row["requests_used_today"] = 0
        client_row["updated_at"] = now_iso
        # Persist
        for i, c in enumerate(api_clients):
            if c.get("id") == client_row.get("id"):
                api_clients[i] = client_row
                break
        _save("api_clients.json", api_clients)

    # Update key last_used_at
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    for i, k in enumerate(api_keys):
        if k.get("id") == key_row.get("id"):
            api_keys[i] = key_row
            break
    _save("api_keys.json", api_keys)

    # Cursor decode: base16 integer offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log(client_row.get("id"), key_row.get("id"), "list_fetch_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            if not cursor.startswith("off_"):
                raise ValueError("bad")
            offset = int(cursor[4:], 10)
            if offset < 0:
                raise ValueError("bad")
        except ValueError:
            _log(client_row.get("id"), key_row.get("id"), "list_fetch_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    fetch_requests = _load("fetch_requests.json")
    if not isinstance(fetch_requests, list):
        fetch_requests = []

    def _created_dt(row):
        s = row.get("created_at")
        if not isinstance(s, str):
            return None
        ss = s
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    # Filter to authenticated client
    rows = [r for r in fetch_requests if r.get("api_client_id") == client_row.get("id")]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if url_contains is not None:
        rows = [r for r in rows if isinstance(r.get("url"), str) and url_contains in r.get("url")]
    if url_normalized is not None:
        rows = [r for r in rows if r.get("url_normalized") == url_normalized]

    if dt_after is not None:
        rows = [r for r in rows if (_created_dt(r) is not None and _created_dt(r) >= dt_after)]
    if dt_before is not None:
        rows = [r for r in rows if (_created_dt(r) is not None and _created_dt(r) <= dt_before)]

    # Sort created_at desc; fallback stable by id
    rows.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""), reverse=True)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = ("off_" + str(next_offset)) if has_more else None

    resp = {
        "data": page,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total
        }
    }

    _log(client_row.get("id"), key_row.get("id"), "list_fetch_requests", "ok", (time.time() - t0) * 1000)
    return resp

def get_fetch_request(api_key, fetch_request_id, include_response=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0389000" if __import__("os").path.isdir("./environment_mix/0389000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _rows(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        return []

    def _write_back(filename, loaded_obj, new_rows):
        if isinstance(loaded_obj, dict) and "rows" in loaded_obj:
            loaded_obj["rows"] = new_rows
            _save(filename, loaded_obj)
        else:
            _save(filename, new_rows)

    def _new_log_id(seed):
        return "rl_" + hashlib.sha256(seed.encode("utf-8")).hexdigest()[:24]

    # Ensure every call is logged, even UNAUTHORIZED/VALIDATION_ERROR; log at return time.
    def _append_log(api_client_id, api_key_id, status, error_code=None):
        logs_obj = _load("request_logs.json")
        logs = _rows(logs_obj)
        latency_ms = int((time.time() - t0) * 1000)
        seed = f"{now_iso}|get_fetch_request|{api_client_id}|{api_key_id}|{len(logs)}|{latency_ms}"
        logs.append({
            "id": _new_log_id(seed),
            "tool_name": "get_fetch_request",
            "api_client_id": api_client_id,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now_iso
        })
        _write_back("request_logs.json", logs_obj, logs)

    # ---- Validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        _append_log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(fetch_request_id, str) or not fetch_request_id.strip():
        _append_log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fetch_request_id must be a non-empty string")
    if include_response is None:
        include_response = False
    if not isinstance(include_response, bool):
        _append_log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_response must be a boolean")

    # ---- Authenticate API key (by id or client-visible prefix), never by secret/hash ----
    keys_obj = _load("api_keys.json")
    keys = _rows(keys_obj)
    key_row = None
    # Prefer exact id match; otherwise allow matching key_prefix (client-visible)
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key:
            key_row = k
            break
    if key_row is None:
        for k in keys:
            if isinstance(k, dict) and k.get("key_prefix") == api_key:
                key_row = k
                break

    if not key_row:
        _append_log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")

    if key_row.get("status") != "active":
        _append_log(key_row.get("api_client_id"), key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is revoked.", api_key_id=key_row.get("id"))

    api_client_id = key_row.get("api_client_id")
    clients_obj = _load("api_clients.json")
    clients = _rows(clients_obj)
    client_row = None
    for c in clients:
        if isinstance(c, dict) and c.get("id") == api_client_id:
            client_row = c
            break
    if not client_row:
        _append_log(api_client_id, key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API client for key not found.", api_client_id=api_client_id)

    # Update last_used_at for successful authentication
    touched = False
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            touched = True
            break
    if touched:
        _write_back("api_keys.json", keys_obj, keys)

    # ---- Retrieve fetch request (must belong to authenticated client) ----
    reqs_obj = _load("fetch_requests.json")
    reqs = _rows(reqs_obj)

    req_row = None
    for r in reqs:
        if isinstance(r, dict) and r.get("id") == fetch_request_id:
            req_row = r
            break

    if not req_row or req_row.get("api_client_id") != api_client_id:
        _append_log(api_client_id, key_row.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Fetch request not found for this client.", fetch_request_id=fetch_request_id)

    result = {"fetch_request": req_row}

    if include_response:
        resps_obj = _load("fetch_responses.json")
        resps = _rows(resps_obj)
        resp_row = None
        for rr in resps:
            if isinstance(rr, dict) and rr.get("fetch_request_id") == fetch_request_id:
                resp_row = rr
                break
        result["fetch_response"] = resp_row  # may be None if not created yet

    _append_log(api_client_id, key_row.get("id"), "ok", None)
    return result

def cancel_fetch_request(api_key, fetch_request_id, reason=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0389000" if __import__("os").path.isdir("./environment_mix/0389000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _rows(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        return []

    def _write_back(filename, loaded_obj, new_rows):
        if isinstance(loaded_obj, dict) and "rows" in loaded_obj:
            loaded_obj["rows"] = new_rows
            _save(filename, loaded_obj)
        else:
            _save(filename, new_rows)

    def _new_log_id(seed):
        return "rl_" + hashlib.sha256(seed.encode("utf-8")).hexdigest()[:24]

    def _append_log(api_client_id, api_key_id, status, error_code=None):
        logs_obj = _load("request_logs.json")
        logs = _rows(logs_obj)
        latency_ms = int((time.time() - t0) * 1000)
        seed = f"{now_iso}|cancel_fetch_request|{api_client_id}|{api_key_id}|{len(logs)}|{latency_ms}"
        logs.append({
            "id": _new_log_id(seed),
            "tool_name": "cancel_fetch_request",
            "api_client_id": api_client_id,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now_iso
        })
        _write_back("request_logs.json", logs_obj, logs)

    # ---- Validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        _append_log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(fetch_request_id, str) or not fetch_request_id.strip():
        _append_log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fetch_request_id must be a non-empty string")
    if reason is not None and not isinstance(reason, str):
        _append_log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reason must be a string when provided")

    # ---- Authenticate API key (by id or client-visible prefix) ----
    keys_obj = _load("api_keys.json")
    keys = _rows(keys_obj)
    key_row = None
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key:
            key_row = k
            break
    if key_row is None:
        for k in keys:
            if isinstance(k, dict) and k.get("key_prefix") == api_key:
                key_row = k
                break

    if not key_row:
        _append_log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")

    if key_row.get("status") != "active":
        _append_log(key_row.get("api_client_id"), key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is revoked.", api_key_id=key_row.get("id"))

    api_client_id = key_row.get("api_client_id")
    clients_obj = _load("api_clients.json")
    clients = _rows(clients_obj)
    client_row = None
    for c in clients:
        if isinstance(c, dict) and c.get("id") == api_client_id:
            client_row = c
            break
    if not client_row:
        _append_log(api_client_id, key_row.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API client for key not found.", api_client_id=api_client_id)

    # Update last_used_at for successful authentication
    for k in keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            _write_back("api_keys.json", keys_obj, keys)
            break

    # ---- Locate request (must belong to this client) ----
    reqs_obj = _load("fetch_requests.json")
    reqs = _rows(reqs_obj)

    idx = None
    req_row = None
    for i, r in enumerate(reqs):
        if isinstance(r, dict) and r.get("id") == fetch_request_id:
            idx = i
            req_row = r
            break

    if not req_row or req_row.get("api_client_id") != api_client_id:
        _append_log(api_client_id, key_row.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Fetch request not found for this client.", fetch_request_id=fetch_request_id)

    # ---- Enforce lifecycle transitions ----
    # queued -> cancelled, running -> cancelled are allowed
    allowed_from = {"queued", "running"}
    current_status = req_row.get("status")
    if current_status not in allowed_from:
        # Spec says raises CONFLICT if transition not allowed
        _append_log(api_client_id, key_row.get("id"), "error", "CONFLICT")
        return _err(
            "CONFLICT",
            "Cancellation is only allowed when status is queued or running (lifecycle rule).",
            fetch_request_id=fetch_request_id,
            current_status=current_status
        )

    # Perform transition
    reqs[idx]["status"] = "cancelled"
    reqs[idx]["updated_at"] = now_iso
    # cancelled is terminal; if request was running, it could have started
    if reqs[idx].get("finished_at") is None:
        reqs[idx]["finished_at"] = now_iso

    # Persist mutation (no success without effect)
    _write_back("fetch_requests.json", reqs_obj, reqs)

    # Store reason for auditing if request row supports arbitrary fields (JSON store); keep conservative.
    # Do NOT error if schema doesn't list it; json store can hold extra keys.
    if reason:
        # Re-load, re-attach reason safely (avoid failing if concurrent save)
        reqs_obj2 = _load("fetch_requests.json")
        reqs2 = _rows(reqs_obj2)
        changed = False
        for i, r in enumerate(reqs2):
            if isinstance(r, dict) and r.get("id") == fetch_request_id and r.get("api_client_id") == api_client_id:
                reqs2[i]["cancel_reason"] = reason
                reqs2[i]["updated_at"] = now_iso
                changed = True
                break
        if changed:
            _write_back("fetch_requests.json", reqs_obj2, reqs2)

    _append_log(api_client_id, key_row.get("id"), "ok", None)
    return {"fetch_request": reqs[idx]}

def list_host_access_policies(api_key, limit=None, cursor=None, status=None, host_pattern=None, policy=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0389000" if __import__("os").path.isdir("./environment_mix/0389000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if not v or not isinstance(v, str):
            return None
        try:
            if v.endswith("Z"):
                v2 = v[:-1]
                return datetime.datetime.fromisoformat(v2)
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    def _log_call(api_client_id, api_key_id, used_key_value, tool_name, status_code, error_code, started_ts):
        latency_ms = int((time.time() - started_ts) * 1000)
        logs = _load("fetch_requests.json")
        # This service has no dedicated audit log collection; record service dynamics into fetch_requests as request log rows.
        # Use a special URL scheme to avoid violating "url like 'http%://%'" constraint for real fetches; these are internal logs.
        # However constraint exists; therefore we store a minimally valid http URL.
        log_row = {
            "id": "log_" + str(int(time.time() * 1000)) + "_" + str(os.getpid()),
            "api_client_id": api_client_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "url": "http://localhost/.internal/log",
            "url_normalized": "http://localhost/.internal/log",
            "headers": {"x-internal-log": True, "x-used-key": used_key_value[:16] if isinstance(used_key_value, str) else None},
            "status": "succeeded" if status_code == "ok" else "failed",
            "attempt": 1,
            "cache_policy": "no_cache",
            "cache_key": "internal_log:" + tool_name,
            "started_at": _now_iso(),
            "finished_at": _now_iso(),
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("fetch_requests.json", logs)

    started_ts = time.time()
    tool_name = "list_host_access_policies"

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled"):
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled")

    if policy is not None:
        if not isinstance(policy, str) or policy not in ("allow", "deny"):
            return _err("VALIDATION_ERROR", "policy must be one of: allow, deny")

    if host_pattern is not None and (not isinstance(host_pattern, str) or host_pattern == ""):
        return _err("VALIDATION_ERROR", "host_pattern must be a non-empty string when provided")

    api_keys = _load("api_keys.json")
    api_clients = _load("api_clients.json")
    host_policies = _load("host_access_policies.json")

    # Authenticate: accept api_key as either api_keys.id or api_keys.key_prefix (client-visible).
    key_row = None
    for r in api_keys:
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            key_row = r
            break

    if not key_row or key_row.get("status") != "active":
        # cannot log with unknown client; record nothing else
        return _err("UNAUTHORIZED", "API key is invalid or revoked")

    client_id = key_row.get("api_client_id")
    client_row = None
    for c in api_clients:
        if c.get("id") == client_id:
            client_row = c
            break
    if not client_row or client_row.get("status") != "active":
        _log_call(client_id, key_row.get("id"), api_key, tool_name, "error", "UNAUTHORIZED", started_ts)
        return _err("UNAUTHORIZED", "Client is not active")

    # Update last_used_at for key on successful authentication
    now = _now_iso()
    mutated = False
    for r in api_keys:
        if r.get("id") == key_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now
            mutated = True
            break
    if mutated:
        _save("api_keys.json", api_keys)

    # Pagination cursor decode: base64url encoded JSON {"created_at": "...", "id":"..."}
    start_after = None
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            payload = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(payload)
            if not isinstance(obj, dict) or "created_at" not in obj or "id" not in obj:
                return _err("VALIDATION_ERROR", "Invalid cursor")
            ca = obj.get("created_at")
            cid = obj.get("id")
            if not isinstance(ca, str) or not isinstance(cid, str):
                return _err("VALIDATION_ERROR", "Invalid cursor")
            start_after = (ca, cid)
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Filter to client-scoped rules effective for authenticated client (client-scoped rules)
    rows = []
    for p in host_policies:
        if p.get("api_client_id") != client_id:
            continue
        if status is not None and p.get("status") != status:
            continue
        if policy is not None and p.get("policy") != policy:
            continue
        if host_pattern is not None and p.get("host_pattern") != host_pattern:
            continue
        rows.append(p)

    # Order by created_at desc, then id desc
    def _sort_key(p):
        dt = _parse_dt(p.get("created_at")) or datetime.datetime(1970, 1, 1)
        return (dt, p.get("id") or "")

    rows.sort(key=_sort_key, reverse=True)

    # Apply cursor: return items strictly after the cursor in this ordering
    if start_after is not None:
        ca, cid = start_after
        ca_dt = _parse_dt(ca)
        if ca_dt is None:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        filtered = []
        for p in rows:
            p_dt = _parse_dt(p.get("created_at")) or datetime.datetime(1970, 1, 1)
            pid = p.get("id") or ""
            if (p_dt, pid) < (ca_dt, cid):
                filtered.append(p)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        obj = {"created_at": last.get("created_at"), "id": last.get("id")}
        token = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = token

    _log_call(client_id, key_row.get("id"), api_key, tool_name, "ok", None, started_ts)
    return {
        "object": "list",
        "data": page,
        "limit": limit,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def upsert_host_access_policy(api_key, host_pattern, policy, host_access_policy_id=None, status=None, reason=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0389000" if __import__("os").path.isdir("./environment_mix/0389000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(api_client_id, api_key_id, used_key_value, tool_name, status_code, error_code, started_ts):
        latency_ms = int((time.time() - started_ts) * 1000)
        logs = _load("fetch_requests.json")
        log_row = {
            "id": "log_" + str(int(time.time() * 1000)) + "_" + str(os.getpid()),
            "api_client_id": api_client_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "url": "http://localhost/.internal/log",
            "url_normalized": "http://localhost/.internal/log",
            "headers": {"x-internal-log": True, "x-used-key": used_key_value[:16] if isinstance(used_key_value, str) else None},
            "status": "succeeded" if status_code == "ok" else "failed",
            "attempt": 1,
            "cache_policy": "no_cache",
            "cache_key": "internal_log:" + tool_name,
            "started_at": _now_iso(),
            "finished_at": _now_iso(),
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("fetch_requests.json", logs)

    started_ts = time.time()
    tool_name = "upsert_host_access_policy"

    # Validate required inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    if not isinstance(host_pattern, str) or host_pattern == "":
        return _err("VALIDATION_ERROR", "host_pattern must be a non-empty string")

    if not isinstance(policy, str) or policy not in ("allow", "deny"):
        return _err("VALIDATION_ERROR", "policy must be one of: allow, deny")

    if host_access_policy_id is not None and (not isinstance(host_access_policy_id, str) or not host_access_policy_id.strip()):
        return _err("VALIDATION_ERROR", "host_access_policy_id must be a non-empty string when provided")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled"):
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled")

    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string when provided")

    # Validate host_pattern syntax: either exact hostname or wildcard "*.example.com"
    # No schemes, paths, ports; basic DNS label checks.
    hp = host_pattern.strip().lower()
    if "/" in hp or "://" in hp or ":" in hp or " " in hp or "\t" in hp:
        return _err("VALIDATION_ERROR", "host_pattern must be a hostname pattern without scheme, port, or path")
    wildcard = False
    if hp.startswith("*."):
        wildcard = True
        base = hp[2:]
    else:
        base = hp

    if base == "" or base.startswith(".") or base.endswith("."):
        return _err("VALIDATION_ERROR", "Invalid host_pattern")

    labels = base.split(".")
    if len(labels) < 2:
        return _err("VALIDATION_ERROR", "host_pattern must contain a registrable domain (e.g., example.com)")
    label_re = re.compile(r"^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$")
    for lab in labels:
        if not lab or len(lab) > 63 or not label_re.match(lab):
            return _err("VALIDATION_ERROR", "Invalid host_pattern")
    if wildcard and len(labels) < 2:
        return _err("VALIDATION_ERROR", "Invalid host_pattern")

    api_keys = _load("api_keys.json")
    api_clients = _load("api_clients.json")
    host_policies = _load("host_access_policies.json")

    # Authenticate (id or key_prefix)
    key_row = None
    for r in api_keys:
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            key_row = r
            break
    if not key_row or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is invalid or revoked")

    client_id = key_row.get("api_client_id")
    client_row = None
    for c in api_clients:
        if c.get("id") == client_id:
            client_row = c
            break
    if not client_row or client_row.get("status") != "active":
        _log_call(client_id, key_row.get("id"), api_key, tool_name, "error", "UNAUTHORIZED", started_ts)
        return _err("UNAUTHORIZED", "Client is not active")

    # Update last_used_at for key on successful authentication
    now = _now_iso()
    for r in api_keys:
        if r.get("id") == key_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    # Default status
    if status is None:
        status = "active"

    # Upsert
    if host_access_policy_id is not None:
        # Update by id; must belong to this client
        target = None
        for p in host_policies:
            if p.get("id") == host_access_policy_id:
                target = p
                break
        if not target:
            _log_call(client_id, key_row.get("id"), api_key, tool_name, "error", "NOT_FOUND", started_ts)
            return _err("NOT_FOUND", "Host access policy not found")

        if target.get("api_client_id") != client_id:
            _log_call(client_id, key_row.get("id"), api_key, tool_name, "error", "UNAUTHORIZED", started_ts)
            return _err("UNAUTHORIZED", "Not authorized for this host access policy")

        # Enforce uniqueness (api_client_id, host_pattern) excluding self
        for p in host_policies:
            if p.get("id") != target.get("id") and p.get("api_client_id") == client_id and p.get("host_pattern") == hp:
                _log_call(client_id, key_row.get("id"), api_key, tool_name, "error", "CONFLICT", started_ts)
                return _err("CONFLICT", "A policy for this host_pattern already exists for this client")

        # Lifecycle transition enforcement
        old_status = target.get("status")
        if old_status not in ("active", "disabled"):
            old_status = "disabled"
        if status != old_status:
            allowed = {"active": ["disabled"], "disabled": ["active"]}.get(old_status, [])
            if status not in allowed:
                _log_call(client_id, key_row.get("id"), api_key, tool_name, "error", "INVALID_TRANSITION", started_ts)
                return _err("INVALID_TRANSITION", f"Cannot transition status from {old_status} to {status}")

        target["host_pattern"] = hp
        target["policy"] = policy
        target["status"] = status
        target["reason"] = reason
        target["updated_at"] = now

        _save("host_access_policies.json", host_policies)
        _log_call(client_id, key_row.get("id"), api_key, tool_name, "ok", None, started_ts)
        return {"object": "host_access_policy", "data": target}

    # Create new policy
    # Enforce uniqueness (api_client_id, host_pattern)
    for p in host_policies:
        if p.get("api_client_id") == client_id and p.get("host_pattern") == hp:
            # Idempotent-ish behavior: update existing with same unique key
            old_status = p.get("status")
            if old_status not in ("active", "disabled"):
                old_status = "disabled"
            if status != old_status:
                allowed = {"active": ["disabled"], "disabled": ["active"]}.get(old_status, [])
                if status not in allowed:
                    _log_call(client_id, key_row.get("id"), api_key, tool_name, "error", "INVALID_TRANSITION", started_ts)
                    return _err("INVALID_TRANSITION", f"Cannot transition status from {old_status} to {status}")
            p["policy"] = policy
            p["status"] = status
            p["reason"] = reason
            p["updated_at"] = now
            _save("host_access_policies.json", host_policies)
            _log_call(client_id, key_row.get("id"), api_key, tool_name, "ok", None, started_ts)
            return {"object": "host_access_policy", "data": p}

    new_id = "hap_" + str(int(time.time() * 1000)) + "_" + str(os.getpid())
    row = {
        "id": new_id,
        "api_client_id": client_id,
        "host_pattern": hp,
        "policy": policy,
        "status": status,
        "reason": reason,
        "created_at": now,
        "updated_at": now,
    }
    host_policies.append(row)
    _save("host_access_policies.json", host_policies)
    _log_call(client_id, key_row.get("id"), api_key, tool_name, "ok", None, started_ts)
    return {"object": "host_access_policy", "data": row}
